#!/usr/bin/env python3
"""Hand edits to the proof packet's README.md and SCOPE.md for HEAD 80e80243 (round 4), applied as
exact string replacements so the edit is reproducible and refuses to run on unexpected text.

Scientific effect: NONE. Documentation only: no label, disposition or status changes; alignment
PENDING_INDEPENDENT_REVIEW; organizational-independence credit 0. Never touches check.py, tests or Lean.
"""
import subprocess
import sys
from pathlib import Path

CLONE = Path('<SCRATCH>/repos/math')
PACKET_REL = 'specifications/lean_statement_proofs_20261011'
PACKET = CLONE / PACKET_REL
HEAD = '80e80243da9de0bd81703bbc2dd19782196fbefe'


def pristine(name: str) -> str:
    """The committed text at HEAD 80e80243 (read-only `git show`; no checkout), so the script
    reproduces the final files from the commit regardless of the worktree's current state."""
    head = subprocess.run(['git', '-C', str(CLONE), 'rev-parse', 'HEAD'], check=True, capture_output=True, text=True).stdout.strip()
    if head != HEAD:
        sys.exit(f'REFUSED: clone HEAD is {head}, expected {HEAD}')
    return subprocess.run(['git', '-C', str(CLONE), 'show', f'{HEAD}:{PACKET_REL}/{name}'], check=True,
                          capture_output=True, text=True, encoding='utf-8').stdout


def replace_once(text: str, old: str, new: str, label: str) -> str:
    n = text.count(old)
    if n != 1:
        sys.exit(f'REFUSED: {label}: expected exactly one occurrence of the old text, found {n}')
    return text.replace(old, new)


